package dev.hexora.controller;
import dev.hexora.enums.MediaType; import dev.hexora.model.Media; import dev.hexora.repository.MediaRepository; import org.springframework.http.ResponseEntity; import org.springframework.http.CacheControl; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.IOException;
@RestController @RequestMapping("/api/media") public class MediaController {private final MediaRepository repo;public MediaController(MediaRepository repo){this.repo=repo;}
 @GetMapping("/public/{id}") ResponseEntity<byte[]> publicFile(@PathVariable Long id){Media m=repo.findById(id).orElseThrow(dev.hexora.api.ApiException::notFound);return ResponseEntity.ok().contentType(org.springframework.http.MediaType.parseMediaType(m.getContentType())).cacheControl(CacheControl.maxAge(java.time.Duration.ofDays(30)).cachePublic()).body(m.getData());}
 @PostMapping("/upload") ResponseEntity<?> upload(@RequestParam MultipartFile file,@RequestParam(defaultValue="IMAGE")MediaType type)throws IOException{if(file.isEmpty()||file.getSize()>5*1024*1024)return ResponseEntity.badRequest().body("Invalid file");Media m=new Media();m.setFileName(file.getOriginalFilename()==null?"upload":file.getOriginalFilename());m.setContentType(file.getContentType()==null?"application/octet-stream":file.getContentType());m.setData(file.getBytes());m.setSize(file.getSize());m.setType(type);repo.save(m);return ResponseEntity.status(201).body(java.util.Map.of("id",m.getId(),"url","/api/media/public/"+m.getId(),"fileName",m.getFileName()));}
 @DeleteMapping("/{id}") ResponseEntity<?> delete(@PathVariable Long id){repo.delete(repo.findById(id).orElseThrow(dev.hexora.api.ApiException::notFound));return ResponseEntity.noContent().build();}}
